WITH lines AS (SELECT id, service, host, level, status_code, attr_key, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS attr_key, v) SELECT id, host, level, status_code, attr_key, COUNT(status_code) OVER w_grp AS running_count_status_code, SUM(status_code) OVER w_grp AS running_sum_status_code, MIN(status_code) OVER w_grp AS running_min_status_code, LEAD(status_code, 1, 0) OVER (PARTITION BY service ORDER BY status_code, id, attr_key) AS next_status_code FROM lines WHERE host IN ('h1', 'h2') WINDOW w_grp AS (PARTITION BY attr_key ORDER BY status_code, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
